import { OperatorFunction } from '../types';
import { operate } from '../util/lift';
import { createOperatorSubscriber } from './OperatorSubscriber';

/**
 * Applies a projection function to each value emitted by the source Observable,
 * passing the current value, the previous source value and the source index.
 *
 * The previous value is `undefined` for the first source emission.
 */
export function mapWithPrevious<T, R>(
  project: (value: T, previous: T | undefined, index: number) => R
): OperatorFunction<T, R> {
  return operate((source, subscriber) => {
    let previous: T | undefined;
    let index = 0;

    source.subscribe(
      createOperatorSubscriber(subscriber, (value: T) => {
        const previousValue = previous;
        previous = value;
        subscriber.next(project(value, previousValue, index++));
      })
    );
  });
}--- tests ---
