describe('mapWithPrevious', () => {
  it('projects the current value, previous value and index', () => {
    const values: Array<[number, number | undefined, number]> = [];

    from([10, 20, 30])
      .pipe(
        mapWithPrevious((current, previous, index) => {
          values.push([current, previous, index]);
          return current;
        })
      )
      .subscribe();

    expect(values).toEqual([
      [10, undefined, 0],
      [20, 10, 1],
      [30, 20, 2],
    ]);
  });

  it('resets the previous value and index for each subscription', () => {
    const source = from([1, 2]).pipe(mapWithPrevious((current, previous, index) => [current, previous, index] as const));
    const first: Array<readonly [number, number | undefined, number]> = [];
    const second: Array<readonly [number, number | undefined, number]> = [];

    source.subscribe((value) => first.push(value));
    source.subscribe((value) => second.push(value));

    expect(first).toEqual([
      [1, undefined, 0],
      [2, 1, 1],
    ]);
    expect(second).toEqual(first);
  });

  it('preserves source errors and completion', () => {
    const error = new Error('test error');
    const notifications: string[] = [];
    const source = new Observable<number>((subscriber) => {
      subscriber.next(1);
      subscriber.error(error);
    });

    source.pipe(mapWithPrevious((current, previous, index) => `${current}:${previous}:${index}`)).subscribe({
      next: (value) => notifications.push(value),
      error: (err) => notifications.push(err.message),
      complete: () => notifications.push('complete'),
    });

    expect(notifications).toEqual(['1:undefined:0', 'test error']);
  });

  it('forwards completion after the final projected value', () => {
    const notifications: Array<string | number> = [];

    from([1, 2])
      .pipe(mapWithPrevious((current, previous, index) => `${current}:${previous}:${index}`))
      .subscribe({
        next: (value) => notifications.push(value),
        complete: () => notifications.push('complete'),
      });

    expect(notifications).toEqual(['1:undefined:0', '2:1:1', 'complete']);
  });

  it('stops listening to a synchronous source when unsubscribed', () => {
    const values: number[] = [];
    const sideEffects: number[] = [];
    const source = new Observable<number>((subscriber) => {
      for (let value = 0; !subscriber.closed && value < 10; value++) {
        sideEffects.push(value);
        subscriber.next(value);
      }
    });

    source.pipe(mapWithPrevious((value) => value), take(2)).subscribe((value) => values.push(value));

    expect(values).toEqual([0, 1]);
    expect(sideEffects).toEqual([0, 1]);
